package com.sih.learningplatform.service;
import com.sih.learningplatform.dto.*; import com.sih.learningplatform.entity.*; import com.sih.learningplatform.exception.ResourceNotFoundException; import com.sih.learningplatform.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.*; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor public class CompetencyService { private final EmployeeRepository employeeRepository; private final RoleCompetencyRepository roleCompetencyRepository;
 public GapAnalysisResponse analyzeGaps(Long id){Employee e=employeeRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Employee not found with ID: "+id)); RoleCompetency r=roleCompetencyRepository.findByDesignationIgnoreCase(e.getDesignation()).orElseThrow(()->new ResourceNotFoundException("No role competency benchmark configured for designation: '"+e.getDesignation()+"'")); Set<String> cur=e.getCurrentSkills().stream().filter(Objects::nonNull).map(s->s.trim().toLowerCase()).collect(Collectors.toSet()); List<String> miss=r.getRequiredSkills().stream().filter(Objects::nonNull).filter(s->!cur.contains(s.trim().toLowerCase())).toList(); double score=r.getRequiredSkills().isEmpty()?100:BigDecimal.valueOf((r.getRequiredSkills().size()-miss.size())*100.0/r.getRequiredSkills().size()).setScale(2,RoundingMode.HALF_UP).doubleValue(); return GapAnalysisResponse.builder().employeeId(e.getId()).employeeName(e.getName()).designation(e.getDesignation()).currentSkills(e.getCurrentSkills()).requiredSkills(r.getRequiredSkills()).missingSkills(miss).competencyMatchPercentage(score).build(); }
}
